SELECT CASE WHEN quantity >= 202 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, ROUND(AVG(quantity), 2) AS avg_quantity, COUNT(DISTINCT store_id) AS distinct_store_ids, PERCENTILE_APPROX(quantity, 0.9) AS quantity_p90, APPROX_PERCENTILE(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, COUNT(*) AS event_count, PERCENTILE_APPROX(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles_2 FROM inventory GROUP BY CASE WHEN quantity >= 202 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY quantity_p90 NULLS FIRST;
